-- Read-only, save on D before applying. Only these four additional functions are replaced.
WITH expected(signature) AS (VALUES ('public.get_documents_kpi(uuid)'),('public.list_recycle_bin(uuid,text,integer,integer)'),('public.soft_delete_document(text,uuid)'),('public.restore_document(text,uuid)')) SELECT e.signature,pg_get_functiondef(p.oid) AS definition,pg_get_userbyid(p.proowner) AS owner,p.proacl FROM expected e LEFT JOIN pg_proc p ON p.oid=to_regprocedure(e.signature);
SELECT p.oid::regprocedure AS signature,CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END AS grantee,a.privilege_type,a.is_grantable,format('GRANT %s ON FUNCTION %s TO %s%s;',a.privilege_type,p.oid::regprocedure,CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(a.grantee)) END,CASE WHEN a.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END) AS restore_grant_sql FROM pg_proc p CROSS JOIN LATERAL aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid IN (to_regprocedure('public.get_documents_kpi(uuid)'),to_regprocedure('public.list_recycle_bin(uuid,text,integer,integer)'),to_regprocedure('public.soft_delete_document(text,uuid)'),to_regprocedure('public.restore_document(text,uuid)'));
SELECT tablename,policyname,permissive,roles,cmd,qual,with_check, 'CREATE POLICY '||quote_ident(policyname)||' ON '||quote_ident(schemaname)||'.'||quote_ident(tablename)||' AS '||permissive||' FOR '||cmd||' TO '||(SELECT string_agg(CASE role_name WHEN 'public' THEN 'PUBLIC' ELSE quote_ident(role_name) END,', ') FROM unnest(roles::text[]) role_name)||COALESCE(' USING ('||qual||')','')||COALESCE(' WITH CHECK ('||with_check||')','')||';' AS restore_policy_sql FROM pg_policies WHERE schemaname='public' AND tablename IN ('journal_instances','journal_entries') ORDER BY tablename,policyname;
